with httpx.Client(timeout=30, trust_env=False, follow_redirects=False) as client, client.stream(
    "POST",
    self.identity["endpoint"] + suffix,
    json=payload,
    headers={"Authorization": "Bearer " + self.api_key},
) as response:
    if response.status_code != 200:
        raise ValueError(f"provider HTTP {response.status_code}; no automatic retry")
    chunks = bytearray()
    for part in response.iter_bytes():
        chunks.extend(part)
        if len(chunks) > 128_000:
            raise ValueError("provider response exceeds bound")

with httpx.Client(timeout=15, follow_redirects=False, trust_env=False) as client, client.stream(
    "POST", self.url, json={"jsonrpc": "2.0", "id": 1, "method": method, "params": params}
) as response:
    response.raise_for_status()
    raw = bytearray()
    for chunk in response.iter_bytes():
        raw.extend(chunk)
        if len(raw) > 2_000_000:
            raise ValueError("RPC response exceeds its bounded limit")
